#ifndef OG_H
#define OG_H

#include <winsock2.h>
#include <windows.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

#include "../../proto/og_proto.h"
#include "../../proto/og_wire.h"

#include "og_version.h"
/* og_modules.h and og_profile.h are generated by the Studio (og-cli build) into the profile build folder, which
   comes first in the include path. The defaults in client/src are a development profile with every module. */
#include "og_modules.h"
#include "og_profile.h"

#define OG_ABI_VERSION 2

#ifdef OG_BUILD
#define OG_API __declspec(dllexport)
#else
#define OG_API __declspec(dllimport)
#endif

/* sha256 */
typedef struct { uint32_t h[8]; uint64_t len; uint8_t buf[64]; size_t n; } og_sha256_ctx;
void og_sha256_init(og_sha256_ctx *c);
void og_sha256_update(og_sha256_ctx *c, const void *d, size_t n);
void og_sha256_final(og_sha256_ctx *c, uint8_t out[32]);
void og_hex(const uint8_t *in, size_t n, char *out); /* out: 2n+1 bytes */
int  og_sha256_file(const char *path, char hex[65]);
int  og_unhex(const char *hex, uint8_t *out, size_t n);

/* log, message box, profile secrets */
void og_log_open(const char *dir);
void og_log(const char *fmt, ...);
int  og_message(const char *text, UINT type);
extern HINSTANCE og_instance;
int  og_contains_i(const char *hay, const char *needle);
/* third-party software that hooks every process (banking protection, overlays, drivers) plus the allowlist
   paths of the signature package: never reported as injection or API hook */
int  og_path_tolerated(const char *path);
/* profile values stored masked in the DLL; unmasked into the caller's buffer */
size_t og_profile_hwid_salt(char *out, size_t cap);
void og_profile_proto_salt(uint8_t out[OG_SALT_LEN]);
void og_profile_build_secret(uint8_t out[32]);
void og_profile_tag(uint8_t out[OG_TAG_LEN]);

/* config (odinguard.ini next to the exe may only change cosmetic and diagnostic values) */
typedef struct {
    int max_windows;      /* local fallback before the server policy arrives, 0 = unlimited */
    int block_vm;
    char build[16];
    char ports[128];      /* game server ports that are protected (from the profile) */
} og_config;
extern og_config og_cfg;
void og_config_load(const char *dir);

extern char og_client_dir[MAX_PATH];
extern DWORD og_main_thread;

/* server policy, received after the handshake */
#define OG_MAX_SIGS 1024
typedef struct { uint16_t id; uint8_t kind; char pattern[256]; } og_signature;
typedef struct {
    volatile LONG received;
    int block_vm, max_windows, alive_interval, input_filter, grf_strict;
    int nsig;
    og_signature sig[OG_MAX_SIGS];
} og_policy_t;
extern og_policy_t og_policy;
extern CRITICAL_SECTION og_policy_lock;

/* net (core) */
int  og_net_init(void);
int  og_net_hooks_intact(void);
void og_net_broadcast_control(const uint8_t *msg, size_t n);   /* to every protected connection */
int  og_net_active_connections(void);
int  og_random(void *p, size_t n);

/* challenges (core; code/time/file types are optional) */
void og_challenge_handle(const og_challenge_msg *c, uint8_t out[OG_RESPONSE_LEN]);

/* module interfaces; a module that is not built in is replaced by a stub, so its code is not in the binary */
#if OG_MOD_HWID
typedef struct { char name[24]; char hex[65]; } og_component;
int  og_hwid_collect(og_component *c, int max, const char *salt);
void og_hwid_unique(const og_component *c, int n, char hex[65]);
void og_identity(uint8_t uid[32], og_component *comp, int *ncomp);
#else
typedef struct { char name[24]; char hex[65]; } og_component;
static inline void og_identity(uint8_t uid[32], og_component *comp, int *ncomp) { (void)comp; memset(uid, 0, 32); *ncomp = 0; }
#endif

#if OG_MOD_INTEGRITY
int  og_hash_module_code(HMODULE m, int which, uint8_t out[32]);        /* BLAKE2b-256 of the canonical image (OG_CANON_*) */
int  og_canon_dump(HMODULE m, int which, const char *path);
int  og_module_range(HMODULE m, int which, uint32_t off, uint32_t len, const uint8_t nonce[16], uint8_t out[32]);
int  og_scan_files(const char *dir, char *out, size_t cap);   /* "name=sha256\n" for exe + dll */
int  og_scan_modules(char *out, size_t cap, int *unknown);    /* loaded modules, '?' = outside client/system dirs */
uint8_t og_integrity_flags(void);                             /* OG_ALIVE_DEBUGGER | OG_ALIVE_HW_BREAKPOINT | OG_ALIVE_API_HOOKED */
extern char og_integrity_detail[];                            /* which API was patched */
#else
static inline int og_hash_module_code(HMODULE m, int which, uint8_t out[32]) { (void)m; (void)which; memset(out, 0, 32); return 0; }
static inline int og_module_range(HMODULE m, int w, uint32_t o, uint32_t l, const uint8_t *n, uint8_t *out) { (void)m; (void)w; (void)o; (void)l; (void)n; (void)out; return OG_CH_ST_UNKNOWN; }
static inline int og_scan_files(const char *d, char *o, size_t c) { (void)d; if (c) o[0] = 0; return 0; }
static inline int og_scan_modules(char *o, size_t c, int *u) { if (c) o[0] = 0; *u = 0; return 0; }
static inline uint8_t og_integrity_flags(void) { return IsDebuggerPresent() ? OG_ALIVE_DEBUGGER : 0; }
#endif

#if OG_MOD_ENV
int  og_is_vm(char *why, size_t cap);
int  og_window_slot_acquire(int max_windows);
#else
static inline int og_is_vm(char *why, size_t cap) { if (cap) why[0] = 0; return 0; }
static inline int og_window_slot_acquire(int max_windows) { (void)max_windows; return 1; }
#endif

#if OG_MOD_CRASH
void og_crash_install(void);
void og_crash_write(EXCEPTION_POINTERS *ep, const char *reason);
void og_crash_note_packet(int outbound, uint16_t id, uint16_t len);
const char *og_crash_last_file(void);
#else
static inline void og_crash_install(void) {}
static inline void og_crash_note_packet(int o, uint16_t i, uint16_t l) { (void)o; (void)i; (void)l; }
#endif

#if OG_MOD_HEARTBEAT
void og_guard_start(void);
void og_guard_scan_now(void);
void og_guard_new_connection(void);
#else
static inline void og_guard_start(void) {}
static inline void og_guard_new_connection(void) {}
#endif

#if OG_MOD_DETECT
void og_detect_reset(void);
int  og_detect_scan(void);   /* reports new hits through OG_C_DETECT, returns unknown injected modules */
#else
static inline void og_detect_reset(void) {}
static inline int  og_detect_scan(void) { return 0; }
#endif

#if OG_MOD_CMDS
void og_cmd_handle(const char *cmd, char *reply, size_t cap);
int  og_cmds_init(void);
#else
static inline void og_cmd_handle(const char *cmd, char *reply, size_t cap) { (void)cmd; if (cap) reply[0] = 0; }
static inline int  og_cmds_init(void) { return 1; }
#endif

#if OG_MOD_INPUT
void og_input_enable(int on);
#else
static inline void og_input_enable(int on) { (void)on; }
#endif

#if OG_MOD_ASSETS
int  og_assets_check(char *detail, size_t cap);   /* 1 = loose-file violation; manifest hits are reported directly */
void og_assets_reset(void);
#else
static inline int og_assets_check(char *detail, size_t cap) { if (cap) detail[0] = 0; return 0; }
static inline void og_assets_reset(void) {}
#endif

#if OG_MOD_SPLASH
void og_splash_show(HINSTANCE inst, DWORD hold_ms);
#else
static inline void og_splash_show(HINSTANCE inst, DWORD hold_ms) { (void)inst; (void)hold_ms; }
#endif

#if OG_MOD_COLORS
int  og_text_init(void);
void og_ui_init(void);
void og_colors_update(uint8_t kind, uint8_t op, const uint8_t *p, size_t n);
#else
static inline int  og_text_init(void) { return 1; }
static inline void og_ui_init(void) {}
static inline void og_colors_update(uint8_t k, uint8_t o, const uint8_t *p, size_t n) { (void)k; (void)o; (void)p; (void)n; }
#endif

#endif
